def decode_substitution_message(key,message):
    mapping={};next_letter=ord('a')
    for char in key:
        if char!=' ' and char not in mapping:mapping[char]=chr(next_letter);next_letter+=1
    return ''.join(' ' if char==' ' else mapping[char] for char in message)

